      "fs.mkdirSync(path.join(racine, \"archives\"));",
      "fs.writeFileSync(path.join(racine, \"public\", \".env\"), \"SESSION_SECRET=CLE_EXEMPLE_ABC123\\n\", \"utf8\");",
      "fs.writeFileSync(path.join(racine, \"public\", \"app.js\"), \"console.log('ok');\\n\", \"utf8\");",
